    ("t", "port", "src", "dst", "vlan", "ethertype", "priority", "length",
     "fcs", "alignment")
)


def validate_qos_check_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != QOS_CHECK_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    # bridges/links/delay/bridge/ports/age/storm/lags/mirror/acl/qos 与 qos
    # 契约一致，复用其全量校验
    (
