        "vlan": None,
        "ethertype": 0x0800,
        "priority": 0,
    }


def service(t, port, count):
    return {"t": t, "port": port, "count": count}


def run_cli(args, files=None):
    """files: {相对名: bytes}，写入临时目录；args 中的文件名相对该目录。"""
    with tempfile.TemporaryDirectory() as tmp:
        paths = {}
        for name, content in (files or {}).items():
            path = os.path.join(tmp, name)
            with open(path, "wb") as handle:
                handle.write(content)
            paths[name] = path
        argv = [sys.executable, SWITCH, args[0]] + [
            paths.get(a, os.path.join(tmp, a)) for a in args[1:]
        ]
        proc = subprocess.run(
            argv, stdout=subprocess.PIPE, stderr=subprocess.PIPE
        )
        logs = {}
        for name in os.listdir(tmp):
            if name.endswith(".log"):
                with open(os.path.join(tmp, name), "rb") as handle:
                    logs[name] = handle.read()
    return proc.returncode, proc.stdout, proc.stderr, logs


def write_inputs(config, events, log_name="out.log"):
    return {
        "config.json": json.dumps(config).encode("utf-8"),
        "events.json": json.dumps(events).encode("utf-8"),
    }, log_name


def record(config, events):
    files, log_name = write_inputs(config, events)
    code, out, err, logs = run_cli(
        ["record", "config.json", "events.json", log_name], files
    )
    assert code == 0, (code, err.decode())
    return out, logs[log_name]


def reload_stdout(config, events):
    files, _ = write_inputs(config, events)
    code, out, err, _ = run_cli(
        ["reload", "config.json", "events.json"], files
    )
    assert code == 0, (code, err.decode())
    return out

def validate_security_config(config):
    if not isinstance(config, dict) or frozenset(config) != SECURITY_CONFIG_KEYS:
        raise InvalidInput("bad config")
    (
        bridges,
        links,
        delay,
        bridge,
        ports,
        age,
        storm,
        lags,
        mirror,
        acl,
        qos,
    ) = validate_qos_config(
        {
            "bridges": config["bridges"],
            "links": config["links"],
            "delay": config["delay"],
            "bridge": config["bridge"],
            "ports": config["ports"],
            "age": config["age"],
            "storm": config["storm"],
            "lags": config["lags"],
            "mirror": config["mirror"],
            "acl": config["acl"],
            "qos": config["qos"],
        }
    )
    security = config["security"]
    if not isinstance(security, list):
        raise InvalidInput("bad security")
    names = {port["name"] for port in ports}
    seen = set()
    statics = set()  # 全局互异的 (vlan, mac)
    parsed = []
    for entry in security:
        if not isinstance(entry, dict) or frozenset(entry) != SECURITY_KEYS:
            raise InvalidInput("bad security entry")
        port = entry["port"]
        limit = entry["limit"]
        action = entry["action"]
        static = entry["static"]
        if not isinstance(port, str) or port not in names or port in seen:
            raise InvalidInput("bad security port")
        seen.add(port)
        if not _is_int(limit) or limit < 0:
            raise InvalidInput("bad security limit")
        if action not in SECURITY_ACTIONS:
            raise InvalidInput("bad security action")
        if not isinstance(static, list):
            raise InvalidInput("bad security static")
        items = []
        for item in static:
            if (
                not isinstance(item, dict)
                or frozenset(item) != SECURITY_STATIC_KEYS
            ):
                raise InvalidInput("bad security static entry")
            mac = item["mac"]
            vlan = item["vlan"]
            if not valid_mac(mac):
                raise InvalidInput("bad security static mac")
            if not _valid_vlan_id(vlan):
                raise InvalidInput("bad security static vlan")
            if (vlan, mac) in statics:
                raise InvalidInput("security static must be globally distinct")
            statics.add((vlan, mac))
            items.append({"mac": mac, "vlan": vlan})
        parsed.append(
            {
                "port": port,
                "limit": limit,
                "action": action,
                "static": items,
            }
        )
    if seen != names:  # 须互异覆盖全部物理口
        raise InvalidInput("security must cover all ports")
    return (
        bridges, links, delay, bridge, ports, age, storm, lags, mirror, acl,
        qos, parsed,
    )


